#include <bits/stdc++.h>
using namespace std;

int main() {
    char board[10][10];

    for (int i = 0; i < 10; ++i)
        for (int j = 0; j < 10; ++j)
            cin >> board[i][j];

    const int dx[] = {0, 1, 1, 1};
    const int dy[] = {1, 0, 1, -1};

    for (int row = 0; row < 10; ++row) {
        for (int col = 0; col < 10; ++col) {
            if (board[row][col] == 'O') continue;

            char original = board[row][col];
            board[row][col] = 'X';

            for (int i = 0; i < 10; ++i) {
                for (int j = 0; j < 10; ++j) {
                    for (int d = 0; d < 4; ++d) {
                        bool valid = true;
                        for (int k = 0; k < 5; ++k) {
                            int x = i + dx[d] * k;
                            int y = j + dy[d] * k;
                            if (x < 0 || x >= 10 || y < 0 || y >= 10 ||
                                board[x][y] != 'X') {
                                valid = false;
                                break;
                            }
                        }
                        if (valid) {
                            cout << "YES\n";
                            return 0;
                        }
                    }
                }
            }

            board[row][col] = original;
        }
    }

    cout << "NO\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<string> board(10);
    for (auto& row : board) cin >> row;

    const int dr[] = {0, 1, 1, 1};
    const int dc[] = {1, 0, 1, -1};

    for (int r = 0; r < 10; ++r) {
        for (int c = 0; c < 10; ++c) {
            for (int d = 0; d < 4; ++d) {
                int xCount = 0, emptyCount = 0;

                for (int k = 0; k < 5; ++k) {
                    int nr = r + dr[d] * k;
                    int nc = c + dc[d] * k;

                    if (nr < 0 || nr >= 10 || nc < 0 || nc >= 10) {
                        xCount = -1;
                        break;
                    }

                    xCount += board[nr][nc] == 'X';
                    emptyCount += board[nr][nc] == '.';
                }

                if (xCount >= 4 && emptyCount <= 1) {
                    cout << "YES\n";
                    return 0;
                }
            }
        }
    }

    cout << "NO\n";
    return 0;
}

