#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    char board[10][10];
    for (auto &row : board)
        for (char &cell : row)
            cin >> cell;

    const int dr[] = {0, 1, 1, 1};
    const int dc[] = {1, 0, 1, -1};

    for (int r = 0; r < 10; ++r) {
        for (int c = 0; c < 10; ++c) {
            for (int d = 0; d < 4; ++d) {
                int endR = r + 4 * dr[d];
                int endC = c + 4 * dc[d];

                if (endR < 0 || endR >= 10 || endC < 0 || endC >= 10)
                    continue;

                int xCount = 0;
                bool hasO = false;

                for (int k = 0; k < 5; ++k) {
                    char cell = board[r + k * dr[d]][c + k * dc[d]];
                    xCount += (cell == 'X');
                    hasO |= (cell == 'O');
                }

                if (!hasO && xCount >= 4) {
                    cout << "YES\n";
                    return 0;
                }
            }
        }
    }

    cout << "NO\n";
    return 0;
}

